.sass-api-probe .mat-badge {
  position: relative;
}
.sass-api-probe .mat-badge.mat-badge {
  overflow: visible;
}
.sass-api-probe .mat-badge-content {
  position: absolute;
  text-align: center;
  display: inline-block;
  border-radius: 50%;
  transition: transform 200ms ease-in-out;
  transform: scale(0.6);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  pointer-events: none;
  background-color: var(--mat-badge-background-color);
  color: var(--mat-badge-text-color);
  font-family: Roboto, sans-serif;
  /* @alternate */
  font-family: var(--mat-badge-text-font, Roboto, sans-serif);
  font-size: 12px;
  /* @alternate */
  font-size: var(--mat-badge-text-size, 12px);
  font-weight: 600;
  /* @alternate */
  font-weight: var(--mat-badge-text-weight, 600);
}
.cdk-high-contrast-active .sass-api-probe .mat-badge-content {
  outline: solid 1px;
  border-radius: 0;
}

.sass-api-probe .mat-badge-disabled .mat-badge-content {
  background-color: var(--mat-badge-disabled-state-background-color);
  color: var(--mat-badge-disabled-state-text-color);
}
.sass-api-probe .mat-badge-hidden .mat-badge-content {
  display: none;
}
.sass-api-probe .ng-animate-disabled .mat-badge-content,
.sass-api-probe .mat-badge-content._mat-animation-noopable {
  transition: none;
}
.sass-api-probe .mat-badge-content.mat-badge-active {
  transform: none;
}
.sass-api-probe .mat-badge-small .mat-badge-content {
  width: 16px;
  height: 16px;
  line-height: 16px;
  font-size: 9px;
  /* @alternate */
  font-size: var(--mat-badge-small-size-text-size, 9px);
}
.sass-api-probe .mat-badge-small.mat-badge-above .mat-badge-content {
  top: -8px;
}
.sass-api-probe .mat-badge-small.mat-badge-below .mat-badge-content {
  bottom: -8px;
}
.sass-api-probe .mat-badge-small.mat-badge-before .mat-badge-content {
  left: -16px;
}
[dir=rtl] .sass-api-probe .mat-badge-small.mat-badge-before .mat-badge-content {
  left: auto;
  right: -16px;
