import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {readFileSync, realpathSync, writeFileSync} from 'node:fs';
import {join, relative} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';

const work = fileURLToPath(new URL('.', import.meta.url));
const require = createRequire('/home/parallels/ngx-compat-material-legacy/package.json');
const sass = require('sass');
assert.ok(sass.info.startsWith('dart-sass\t1.104.1\t'));
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const originalRoot = '/tmp/closeout-original16-sass-sources-20261007/node_modules';
const identity = JSON.parse(readFileSync('/tmp/closeout-original16-sass-sources-20261007/source-identities.json'));
const originalSources = new Map(identity.packages.flatMap(row => row.sources.map(source => [row.package + '/' + source.path, source])));
const selected = ['mixin-css/badge-theme', 'mixin-css/datepicker-density', 'mixin-css/datepicker-theme'];
for (const [suffix, line] of [['main', 'main'], ['21', '21.x']]) {
  const root = '/home/parallels/.codex/worktrees/codex-closeout-' + suffix + '/ngx-compat-material-legacy';
  const library = root + '/projects/ngx-material-legacy';
  const peers = '/tmp/closeout-form-field-minimum-sass-20261008/' + line + '/node_modules';
  const model = await import(pathToFileURL(root + '/scripts/sass-default-mapped-companion-contract.mjs'));
  const api = await import(pathToFileURL(root + '/scripts/sass-api-inventory.mjs'));
  const rows = [];
  for (const id of selected) {
    const entry = model.DEFAULT_MAPPED_COMPANION_CASES[id];
    const original = api.compileInvocation(sass, pathToFileURL(originalRoot + '/@angular/material/_index.scss').href, [originalRoot], entry.call);
    assert.equal(original.error, null);
    assert.equal(hash(original.css), entry.original_sha256);
    assert.equal(original.css, entry.original_css);
    const originalLoaded = original.loaded.map(url => {
      const path = realpathSync(fileURLToPath(url));
      const name = relative(originalRoot, path).replaceAll('\\', '/');
      const expected = originalSources.get(name), raw = readFileSync(path);
      assert.ok(expected, 'original loaded an unauthenticated source: ' + name);
      assert.equal(hash(raw), expected.sha256);
      assert.equal(raw.length, expected.bytes);
      return {path: name, sha256: hash(raw), bytes: raw.length};
    });
    const compiled = api.compileInvocation(sass, pathToFileURL(library + '/_index.scss').href, [peers], entry.call);
    assert.equal(compiled.error, null);
    const bases = [library, peers + '/@angular/material', peers + '/@angular/cdk'].map(path => realpathSync(path));
    const sources = compiled.loaded.map(url => {
      const path = realpathSync(fileURLToPath(url));
      const index = bases.findIndex(base => path === base || path.startsWith(base + '/'));
      assert.ok(index >= 0, 'candidate loaded a foreign source');
      const raw = readFileSync(path);
      return {root: index, path: relative(bases[index], path).replaceAll('\\', '/'), sha256: hash(raw), bytes: raw.length};
    }).sort((a,b) => a.root - b.root || a.path.localeCompare(b.path));
    const program = "@use '__entry__' as m;\n" + api.standardThemeSource() + '\n' + entry.call + '\n';
    assert.equal(hash(program), entry.program_sha256);
    const measurement = {line, css: compiled.css, css_sha256: hash(compiled.css), css_bytes: Buffer.byteLength(compiled.css),
      program_sha256: hash(program), sass_version: sass.info, sources};
    const measurementOkay = model.defaultMappedCompanionMeasurementOk(id, measurement, line);
    const peer = model.measureDefaultMappedCompanionPeer({sass, materialRoot: bases[1], cdkRoot: bases[2], caseId: id, line});
    const expected = model.defaultMappedCompanionExpectedCss(id, peer);
    const actual = {css: compiled.css, sha256: hash(compiled.css), actual_measurement: measurement};
    const contract = {classification: 'conforming-current-companion', contract: model.DEFAULT_MAPPED_COMPANION_CONTRACT, peer};
    const pass = measurementOkay && expected !== null && model.defaultMappedCompanionResultsMatch(id, actual, contract);
    rows.push({case_id: id, line, pass, measurement_okay: measurementOkay, expected_contract_available: expected !== null,
      original_css: original.css, original_css_sha256: hash(original.css), original_loaded: originalLoaded,
      actual, contract, expected_css: expected});
    console.log(JSON.stringify({line, id, pass, measurement_okay: measurementOkay, expected_contract_available: expected !== null,
      actual_css_bytes: Buffer.byteLength(compiled.css), expected_css_bytes: expected === null ? null : Buffer.byteLength(expected)}));
  }
  writeFileSync(join(work, suffix + '.json'), JSON.stringify({schema_version: 1, line, node: process.version, sass: sass.info,
    scope: 'Three source-only default badge/datepicker cases; no packed, Angular runtime, rendered, full Sass or canonical qualification.', rows}, null, 2) + '\n', {flag: 'wx'});
  assert.ok(rows.every(row => row.pass), 'source contract mismatch on ' + line);
}

