import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {join} from 'node:path';

const work = fileURLToPath(new URL('.', import.meta.url));
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
for (const suffix of ['main', '21']) {
  const root = '/home/parallels/.codex/worktrees/codex-closeout-' + suffix + '/ngx-compat-material-legacy';
  const model = await import(pathToFileURL(root + '/scripts/sass-default-mapped-companion-contract.mjs'));
  const report = JSON.parse(readFileSync(join(work, suffix + '.json')));
  let rejected = 0;
  for (const row of report.rows) {
    assert.ok(model.defaultMappedCompanionResultsMatch(row.case_id, row.actual, row.contract));
    const altered = structuredClone(row.actual);
    altered.css += '\n.unexpected-contract-rule { color: red; }';
    altered.sha256 = hash(altered.css);
    Object.assign(altered.actual_measurement, {css: altered.css, css_sha256: altered.sha256, css_bytes: Buffer.byteLength(altered.css)});
    assert.equal(model.defaultMappedCompanionResultsMatch(row.case_id, altered, row.contract), false);
    rejected++;
    const foreign = structuredClone(row.contract);
    foreign.peer.line = row.line === 'main' ? '21.x' : 'main';
    assert.equal(model.defaultMappedCompanionResultsMatch(row.case_id, row.actual, foreign), false);
    rejected++;
  }
  writeFileSync(join(work, suffix + '-negatives.json'), JSON.stringify({line: report.line, actual_source_cases: report.rows.length,
    source_cases_rechecked: true, wrong_nonempty_rehashed_css_and_foreign_line_controls_rejected: rejected,
    additional_sass_compilations: 0}, null, 2) + '\n', {flag: 'wx'});
  console.log(JSON.stringify({line: report.line, source_cases: report.rows.length, negative_controls: rejected}));
}
